import request from 'supertest';
import type { Response } from 'supertest';
import { describe, expect, it } from 'vitest';
import { createApp } from '../src/app.ts';
import { ProblemSchema } from '../src/lib/problem.ts';

function expectProblem(res: Response, status: number, slug: string) {
  expect(res.status).toBe(status);
  expect(res.headers['content-type']).toMatch(/^application\/problem\+json/);
  const problem = ProblemSchema.parse(res.body);
  expect(problem.status).toBe(status);
  expect(problem.type).toBe(`https://api.sf/problems/${slug}`);
  return problem;
}

describe('Users API', () => {
  it('POST /v1/users creates a user and returns 201 with Location header', async () => {
    const app = createApp();
    const res = await request(app).post('/v1/users').send({
      email: 'alice@example.com',
      name: 'Alice',
    });
    expect(res.status).toBe(201);
    expect(res.headers['content-type']).toMatch(/^application\/json/);
    expect(res.headers.location).toBeDefined();
    expect(res.headers.location).toMatch(/^\/v1\/users\/[a-f0-9-]+$/);
    expect(res.body).toHaveProperty('id');
    expect(res.body).toHaveProperty('email', 'alice@example.com');
    expect(res.body).toHaveProperty('name', 'Alice');
    expect(res.body).toHaveProperty('role', 'member');
    expect(res.body).toHaveProperty('createdAt');
    expect(res.body).toHaveProperty('updatedAt');
  });

  it('POST /v1/users defaults role to member when omitted', async () => {
    const app = createApp();
    const res = await request(app).post('/v1/users').send({
      email: 'bob@example.com',
      name: 'Bob',
    });
    expect(res.status).toBe(201);
    expect(res.body.role).toBe('member');
  });

  it('POST /v1/users accepts role when specified', async () => {
    const app = createApp();
    const res = await request(app).post('/v1/users').send({
      email: 'charlie@example.com',
      name: 'Charlie',
      role: 'admin',
    });
    expect(res.status).toBe(201);
    expect(res.body.role).toBe('admin');
  });

  it('POST /v1/users returns 409 when email already exists', async () => {
    const app = createApp();
    await request(app).post('/v1/users').send({
      email: 'duplicate@example.com',
      name: 'User One',
    });
    const res = await request(app).post('/v1/users').send({
      email: 'duplicate@example.com',
      name: 'User Two',
    });
    const problem = expectProblem(res, 409, 'conflict');
    expect(problem.detail).toContain('duplicate@example.com');
  });

  it('POST /v1/users returns 422 when email is missing', async () => {
    const app = createApp();
    const res = await request(app).post('/v1/users').send({
      name: 'Invalid User',
    });
    const problem = expectProblem(res, 422, 'validation');
    expect(problem.detail).toContain('email');
  });

  it('POST /v1/users returns 422 when name is missing', async () => {
    const app = createApp();
    const res = await request(app).post('/v1/users').send({
      email: 'nope@example.com',
    });
    const problem = expectProblem(res, 422, 'validation');
    expect(problem.detail).toContain('name');
  });

  it('POST /v1/users returns 422 when email is invalid', async () => {
    const app = createApp();
    const res = await request(app).post('/v1/users').send({
      email: 'not-an-email',
      name: 'Bad Email',
    });
    const problem = expectProblem(res, 422, 'validation');
    expect(problem.detail).toContain('email');
  });

  it('POST /v1/users returns 422 when name is empty', async () => {
    const app = createApp();
    const res = await request(app).post('/v1/users').send({
      email: 'valid@example.com',
      name: '',
    });
    const problem = expectProblem(res, 422, 'validation');
    expect(problem.detail).toContain('name');
  });

  it('POST /v1/users returns 422 when name exceeds max length', async () => {
    const app = createApp();
    const res = await request(app).post('/v1/users').send({
      email: 'valid@example.com',
      name: 'a'.repeat(101),
    });
    const problem = expectProblem(res, 422, 'validation');
    expect(problem.detail).toContain('name');
  });

  it('POST /v1/users returns 422 when role is invalid', async () => {
    const app = createApp();
    const res = await request(app).post('/v1/users').send({
      email: 'valid@example.com',
      name: 'Valid Name',
      role: 'superuser',
    });
    const problem = expectProblem(res, 422, 'validation');
    expect(problem.detail).toContain('role');
  });

  it('POST /v1/users returns 400 when JSON is malformed', async () => {
    const app = createApp();
    const res = await request(app)
      .post('/v1/users')
      .set('Content-Type', 'application/json')
      .send('{"email":');
    expectProblem(res, 400, 'malformed-json');
  });

  it('GET /v1/users returns paginated users', async () => {
    const app = createApp();
    await request(app).post('/v1/users').send({
      email: 'user1@example.com',
      name: 'User One',
    });
    await request(app).post('/v1/users').send({
      email: 'user2@example.com',
      name: 'User Two',
    });

    const res = await request(app).get('/v1/users');
    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('data');
    expect(res.body).toHaveProperty('nextCursor');
    expect(Array.isArray(res.body.data)).toBe(true);
    expect(res.body.data.length).toBe(2);
    expect(res.body.nextCursor).toBeNull();
  });

  it('GET /v1/users respects limit parameter', async () => {
    const app = createApp();
    for (let i = 0; i < 5; i++) {
      await request(app).post('/v1/users').send({
        email: `user${i}@example.com`,
        name: `User ${i}`,
      });
    }

    const res = await request(app).get('/v1/users?limit=2');
    expect(res.status).toBe(200);
    expect(res.body.data.length).toBe(2);
    expect(res.body.nextCursor).toBeDefined();
  });

  it('GET /v1/users default limit is 20', async () => {
    const app = createApp();
    for (let i = 0; i < 5; i++) {
      await request(app).post('/v1/users').send({
        email: `user${i}@example.com`,
        name: `User ${i}`,
      });
    }

    const res = await request(app).get('/v1/users');
    expect(res.status).toBe(200);
    expect(res.body.data.length).toBe(5);
  });

  it('GET /v1/users follows nextCursor to visit every user exactly once', async () => {
    const app = createApp();
    const users: string[] = [];
