import { randomUUID } from 'node:crypto';
import type { Request, Response } from 'express';
import { Router } from 'express';
import { z } from 'zod';
import {
  badRequest,
  conflict,
  notFound,
  sendProblem,
  unprocessable,
} from '../lib/problem.ts';
import {
  CursorQuerySchema,
  paginate,
  pageSchema,
} from '../lib/pagination.ts';
import { idempotency } from '../lib/idempotency.ts';

// Schema definitions
const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: z.enum(['admin', 'member']),
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});

type User = z.infer<typeof UserSchema>;

const CreateUserSchema = z.object({
  email: z.string().email('email must be a valid email address'),
  name: z.string().min(1, 'name is required and must not be empty').max(100, 'name must not exceed 100 characters'),
  role: z.enum(['admin', 'member']).default('member'),
});

type CreateUserInput = z.infer<typeof CreateUserSchema>;

const UpdateUserSchema = z.object({
  email: z.string().email('email must be a valid email address').optional(),
  name: z.string().min(1, 'name must not be empty').max(100, 'name must not exceed 100 characters').optional(),
  role: z.enum(['admin', 'member']).optional(),
});

type UpdateUserInput = z.infer<typeof UpdateUserSchema>;

// Store to hold users in memory
interface UsersStore {
  users: Map<string, User>;
  idempotencyCache: Map<string, { response: object; status: number }>;
}

// Helper function to format validation errors
function formatValidationError(error: z.ZodError): string {
  const issues = error.issues
    .map((issue) => {
      const field = issue.path.join('.');
      return `${field || issue.code}: ${issue.message}`;
    })
    .join('; ');
  return issues;
}

export function createUsersRouter(store: UsersStore): Router {
  const router = Router();

  // POST /v1/users - Create a user
  router.post(
    '/',
    idempotency(),
    (req: Request, res: Response) => {
      // Parse and validate request body
      const parseResult = CreateUserSchema.safeParse(req.body);
      if (!parseResult.success) {
        const detail = formatValidationError(parseResult.error);
        return sendProblem(res, unprocessable(detail));
      }

      const input = parseResult.data;

      // Check if email already exists
      for (const user of store.users.values()) {
        if (user.email === input.email) {
          return sendProblem(
            res,
            conflict(`A user with email ${input.email} already exists`)
          );
        }
      }

      // Create new user
      const now = new Date().toISOString();
      const newUser: User = {
        id: randomUUID(),
        email: input.email,
        name: input.name,
        role: input.role,
        createdAt: now,
        updatedAt: now,
      };

      store.users.set(newUser.id, newUser);

      // Return 201 with Location header
      res.status(201).set('Location', `/v1/users/${newUser.id}`).json(newUser);
    }
  );

  // GET /v1/users - List users with cursor pagination
  router.get('/', (req: Request, res: Response) => {
    // Parse and validate query parameters
    const queryResult = CursorQuerySchema.safeParse(req.query);
    if (!queryResult.success) {
      const detail = formatValidationError(queryResult.error);
      return sendProblem(res, unprocessable(detail));
    }

    const query = queryResult.data;
    const users = Array.from(store.users.values());

    // Sort users by ID for consistent pagination
    users.sort((a, b) => a.id.localeCompare(b.id));

    // Paginate
    const page = paginate(users, query, (user) => user.id);

    // Parse and validate response
    const PageSchema = pageSchema(UserSchema);
    const responseData = PageSchema.parse(page);

    res.status(200).json(responseData);
  });

  // GET /v1/users/:userId - Get a specific user
  router.get('/:userId', (req: Request, res: Response) => {
    const { userId } = req.params;

    // Validate that userId is a valid UUID
    if (!z.string().uuid().safeParse(userId).success) {
      return sendProblem(res, notFound(`User not found`));
    }

    const user = store.users.get(userId);
    if (!user) {
      return sendProblem(res, notFound(`User not found`));
    }

    res.status(200).json(user);
  });

  // PATCH /v1/users/:userId - Update a user
  router.patch('/:userId', idempotency(), (req: Request, res: Response) => {
    const { userId } = req.params;

    // Validate that userId is a valid UUID
    if (!z.string().uuid().safeParse(userId).success) {
      return sendProblem(res, notFound(`User not found`));
    }

    const user = store.users.get(userId);
    if (!user) {
      return sendProblem(res, notFound(`User not found`));
    }

    // Check if patch body is empty
    if (Object.keys(req.body).length === 0) {
      return sendProblem(
        res,
        unprocessable('At least one field must be provided for update')
      );
    }

    // Parse and validate patch body
    const parseResult = UpdateUserSchema.safeParse(req.body);
    if (!parseResult.success) {
      const detail = formatValidationError(parseResult.error);
      return sendProblem(res, unprocessable(detail));
    }

    const updates = parseResult.data;

    // Check if new email already exists (for another user)
    if (updates.email && updates.email !== user.email) {
      for (const otherUser of store.users.values()) {
        if (otherUser.id !== userId && otherUser.email === updates.email) {
          return sendProblem(
            res,
            conflict(`A user with email ${updates.email} already exists`)
          );
        }
      }
    }

    // Apply updates
    const updatedUser: User = {
      ...user,
      ...updates,
      updatedAt: new Date().toISOString(),
    };

    store.users.set(userId, updatedUser);

    res.status(200).json(updatedUser);
  });

  // DELETE /v1/users/:userId - Delete a user
  router.delete('/:userId', (req: Request, res: Response) => {
    const { userId } = req.params;

    // Validate that userId is a valid UUID
    if (!z.string().uuid().safeParse(userId).success) {
      return sendProblem(res, notFound(`User not found`));
    }

    const user = store.users.get(userId);
    if (!user) {
      return sendProblem(res, notFound(`User not found`));
    }

    store.users.delete(userId);
    res.status(204).send();
  });

  return router;
}

